<div class="dashboard-wrap"><h1>Your Shopping Cart</h1><?php if(!$cart): ?><div class="form-card"><p>Your cart is empty.</p><a class="btn btn-primary" href="<?=base_url()?>">Continue Shopping</a></div><?php else: ?><?=form_open('cart/update')?><table class="cart-table"><thead><tr><th>Product</th><th>Price</th><th>Qty</th><th>Subtotal</th><th></th></tr></thead><tbody><?php $total=0;foreach($cart as $i):$sub=$i['price']*$i['qty'];$total+=$sub; ?><tr><td><img class="cart-img" src="<?=base_url('assets/image/'.$i['image'])?>"> <?=html_escape($i['name'])?></td><td><?=money($i['price'])?></td><td><input type="number" min="1" name="qty[<?=$i['id']?>]" value="<?=$i['qty']?>" style="width:70px"></td><td><?=money($sub)?></td><td><a class="btn btn-danger" href="<?=base_url('cart/remove/'.$i['id'])?>">Remove</a></td></tr><?php endforeach; ?></tbody></table><div class="summary"><strong>Total: <?=money($total)?></strong><br><button class="btn btn-secondary">Update Cart</button> <a class="btn btn-primary" href="<?=base_url('checkout')?>">Proceed to Checkout</a> <a class="btn btn-danger" href="<?=base_url('cart/empty')?>">Empty Cart</a></div></form><?php endif; ?></div>
